/**
 * The link-preview image served at /og.png (1200x630 PNG, base64). Chat apps
 * and social cards read it from the og:image tag in every page head.
 * Source: assets/og-card.html — see assets/README.md to re-render.
 */
export const OG_PNG_B64 =
  "";

export const OG_WIDTH = 1200;
export const OG_HEIGHT = 630;

/** Decode the embedded PNG to an ArrayBuffer for serving as a Response body. */
export function ogPngBytes(): ArrayBuffer {
  const bin = atob(OG_PNG_B64);
  const arr = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) arr[i] = bin.charCodeAt(i);
  return arr.buffer;
}
